import logging
from taf.internal.file.transfer.base import FilePutter
from taf.internal.managedobject import Using
from .file_transfer_base import CatFileTransfer

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class CatFilePutter(Using('remote_executor'),
                    Using('local_executor'),
                    FilePutter,
                    CatFileTransfer):

    def put_file(self, source_path, target_path):
        logger.debug(
            "putting {source_path!r} into {target_path!r}".format(
                source_path=source_path,
                target_path=target_path))
        self._transfer_file(source_path=source_path,
                            target_path=target_path,
                            source_executor=self._local_executor,
                            target_executor=self._remote_executor)
